#pragma once
#include <string>

#include "core/nonlinear_combinations.h"
#include "core/undo_stack.h"

namespace cc::core {

struct Project;

/// Replaces Project::nonlinearCombinations as one undoable step: the «Aceptar» of the dialog «Combinaciones no lineales» and the write-back of
/// the combinations regenerated by «Cálculo» («Actualizar las combinaciones no lineales tras el análisis lineal», T-P8-06).
class NonlinearCombinationsCommand : public UndoCommand {
public:
    NonlinearCombinationsCommand(Project& project, NonlinearCombinations after, std::string text);
    void redo() override;
    void undo() override;
    std::string text() const override { return m_text; }

private:
    Project& m_project;
    NonlinearCombinations m_before, m_after;
    std::string m_text;
};

/// Pushes the command when `after` differs from the project's set; false when there is nothing to change.
bool setNonlinearCombinations(Project& project, UndoStack& stack, NonlinearCombinations after,
                              std::string text = "Combinaciones no lineales");

/// Validation of the data of the dialog (clone rules, the original's limits are [N]): a non-blank reference and at least one load step.
/// Empty when valid; otherwise an es-ES message.
std::string validateNonlinearCombinations(const NonlinearCombinations& set);

}  // namespace cc::core
